class RevCollectionError(DvcException):
    """Thrown if a revision failed to be collected.

    Args:
        rev (str): revision that failed (or "workspace").
    """

    def __init__(self, rev):
        self.rev = rev
        super().__init__(f"Failed to collect '{rev}'")


class PromptError(DvcException):
    """Thrown when a prompt is required but the user does not confirm."""

    def __init__(self, path):
        super().__init__(f"unable to remove '{path}' without a confirmation. Use `-f` to force.")
